def construct_sequence(n):
    # Convert n to binary and remove the '0b' prefix
    binary_n = bin(n)[2:]

    # Initialize the sequence with '1'
    sequence = ['1']

    # Iterate over the binary representation of n
    for bit in binary_n:
        if bit == '1':
            # Append '3337' to the sequence for each '1' in the binary representation
            sequence.extend(['3', '3', '3', '7'])
        else:
            # Append '3' to the sequence for each '0' in the binary representation
            sequence.append('3')

    return ''.join(sequence)

